import { useMemo, useState, FormEvent } from 'react';
import { JxTextField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'member', label: 'Участник' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [successOpen, setSuccessOpen] = useState(false);

  const isEmailValid = useMemo(() => EMAIL_PATTERN.test(email.trim()), [email]);
  const showEmailError = email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid && role.length > 0;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSuccessOpen(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)', maxWidth: '420px' }}>
      {successOpen && (
        <JxAlert variant="success" title="Приглашение отправлено" onDismiss={() => setSuccessOpen(false)}>
          {`Приглашение для ${email} было успешно отправлено.`}
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
      >
        <JxTextField
          label="Электронная почта"
          type="email"
          placeholder="name@company.com"
          value={email}
          onValueChange={setEmail}
          hint="Мы отправим приглашение на этот адрес."
          error={showEmailError}
          errorMessage={showEmailError ? 'Введите корректный адрес электронной почты.' : undefined}
          required
        />

        <JxSelect
          label="Роль в команде"
          value={role}
          onValueChange={setRole}
          options={ROLE_OPTIONS}
          placeholder="Выберите роль"
          required
        />

        <JxSwitch
          label="Отправить уведомление"
          description="Пользователь получит письмо с приглашением."
          value={notify}
          onValueChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

